// NHMRC issuer-defined GNT encoding; primary authority independently pinned and retained.
(ReadFile as function, ArchiveBase as text, ExpectedBatch as text, TrustedRuleSHA256 as text) as list =>
let
    Manifest=Json.Document(ReadFile(ArchiveBase&"/manifest.json")),
    Checked=if Manifest[kind]="nhmrc_gnt_crosswalk_retention_v1" and Manifest[batch]=ExpectedBatch and Manifest[namespace]="nhmrc" and Manifest[complete]=true then Manifest else error "Crossref award packet identity drift",
    ReadRaw=(Name as text) as binary => let F=List.Select(Checked[files],each [name]=Name),B=Binary.Buffer(ReadFile(ArchiveBase&"/"&Name)),Pinned=if Name="rule-authority.json" then F else List.Select(Rule[source_files],each [name]=Name),Valid=List.Count(F)=1 and List.Count(Pinned)=1 and F{0}[sha256]=Pinned{0}[sha256] and F{0}[bytes]=Pinned{0}[bytes] and Binary.Length(B)=F{0}[bytes] in if Valid then B else error "Crossref award file identity or length drift",
    Read=(Name as text) as record => Json.Document(ReadRaw(Name)),
    RuleEntries=List.Select(Checked[files],each [name]="rule-authority.json"),
    Rule=if List.Count(RuleEntries)=1 and RuleEntries{0}[sha256]=TrustedRuleSHA256 and Text.Length(TrustedRuleSHA256)=64 then Read("rule-authority.json") else error "External GNT rule authority drift",
    GuideEntries=List.Select(Checked[files],each [name]="guide.pdf"),
    MigrationEntries=List.Select(Checked[files],each [name]="migration-web-readback.json"),
    Policy=if Rule[rule]="nhmrc-rgms-gnt-v1" and Rule[guide_page]=43 and Rule[guide_url]="https://www.nhmrc.gov.au/sites/default/files/2019-03/rgms-user-guide-grant-administration.pdf" and Rule[guide_sha256]="92c37f512dca324ae2da039f3dea11a69d5f0901044c893d908ea11232477a3a" and Rule[migration_url]="https://www.nhmrc.gov.au/sapphire/sapphire-recent-updates" and List.Count(GuideEntries)=1 and GuideEntries{0}[sha256]=Rule[guide_sha256] and Binary.Length(ReadRaw("guide.pdf"))=GuideEntries{0}[bytes] and List.Count(MigrationEntries)=1 and MigrationEntries{0}[sha256]=Rule[migration_sha256] and Binary.Length(ReadRaw("migration-web-readback.json"))=MigrationEntries{0}[bytes] then Rule else error "GNT primary authority drift",
    GrantNumber=(N as text) as nullable text => let D=if Text.Length(N)>=3 then Text.Range(N,3) else "",Code=Text.StartsWith(N,"GNT") and Text.Length(N)=10 and Text.Select(D,{"0".."9"})=D,B=if Text.StartsWith(D,"0") then Text.Range(D,1) else D in if Code and not Text.StartsWith(B,"0") then B else null,
    Historical=(R as record) as logical => try Value.Is(R[startDate],type number) and Value.Is(R[endDate],type number) and Number.Mod(R[startDate],1)=0 and Number.Mod(R[endDate],1)=0 and R[startDate]>=1900 and R[startDate]<=2020 and R[endDate]>=2022 and R[endDate]<=9999 otherwise false,
    AuthorityEntries=List.Select(Checked[files],each [name]="authority-ror.json"),
    Authority=if List.Count(AuthorityEntries)=1 then Read("authority-ror.json") else error "Crossref authority provenance hash drift",
    AuthorityROR=if List.AnyTrue(List.Transform(Authority[links],each [type]="website" and [value]="https://www.nhmrc.gov.au/")) then Authority[id] else error "Crossref award funder authority drift",
    FunderIDs=List.Buffer(List.Combine(List.Transform(List.Select(Authority[external_ids],each [type]="fundref"),each List.Transform([all],(V)=>"10.13039/"&V)))),
    DOI=(S as text) as text => let T=Text.Lower(Text.Trim(S)),Prefixes={"https://doi.org/","http://doi.org/","https://dx.doi.org/","http://dx.doi.org/"},P=List.First(List.Select(Prefixes,each Text.StartsWith(T,_)),null) in if P=null then T else Text.Range(T,Text.Length(P)),
    Lookups=List.Buffer(List.Transform(Policy[ardc],(Q)=>let D=Read(Q[filename]),F=List.Select(Checked[files],each [name]=Q[filename]),Valid=Q[complete]=true and D[status]="OK" and D[code]="200" and D[data][offset]=0 and D[data][numFound]=List.Count(D[data][records]) and List.Count(F)=1 and Q[sha256]=F{0}[sha256] in if Valid then [Query=Q,Records=List.Buffer(D[data][records])] else error "Incomplete Crossref grant lookup")),
    Rows=List.Combine(List.Transform(Policy[crossref],(Q)=>let D=Read(Q[filename]),W=D[message],P=DOI(Q[doi]),F=List.Select(Checked[files],each [name]=Q[filename]),Valid=D[status]="ok" and DOI(W[DOI])=P and Text.StartsWith(P,"10.") and List.Count(F)=1 and Q[sha256]=F{0}[sha256],Funders=if Valid then Record.FieldOrDefault(W,"funder",{}) else error "Crossref publication identity drift" in List.Combine(List.Transform(Funders,(FR)=>let FID=DOI(Record.FieldOrDefault(FR,"DOI","")),Numbers=if List.Contains(FunderIDs,FID) then Record.FieldOrDefault(FR,"award",{}) else {} in List.RemoveNulls(List.Transform(Numbers,(N)=>let
        Ls=List.Select(Lookups,each [Query][original_identifier]=N),L=if List.Count(Ls)=1 then Ls{0} else null,Bare=GrantNumber(N),URI=if Bare=null then null else "https://purl.org/au-research/grants/nhmrc/"&Bare,
        Matches=if L=null or Bare=null then {} else List.Select(L[Records],each Record.FieldOrDefault(_,"type","")="grant" and Record.FieldOrDefault(_,"purl","")=URI and List.Contains(Record.FieldOrDefault(_,"identifiers",{}),Bare)),
        Provenance=if L=null then "" else Text.FromBinary(Json.FromValue([relationship="issuer_defined_grant_code",funderDOI=FID,awardNumber=N,grantNumber=Bare,rule=Policy[rule],ruleAuthoritySHA256=TrustedRuleSHA256,guideSHA256=Policy[guide_sha256],guideURL=Policy[guide_url],guidePage=43,migrationURL=Policy[migration_url],migrationSHA256=Policy[migration_sha256],grantStartYear=if List.Count(Matches)=1 then Matches{0}[startDate] else null,grantEndYear=if List.Count(Matches)=1 then Matches{0}[endDate] else null,ardcRawSHA256=L[Query][sha256],ardcSourceURL=L[Query][url],authorityROR=AuthorityROR,authorityRawSHA256=AuthorityEntries{0}[sha256]]),TextEncoding.Utf8)
        in if List.Count(Matches)=1 and Historical(Matches{0}) then [EvidenceKey=Text.Combine({"crossref:"&P,"publication_award_crosswalk","doi:"&P,URI},"|"),RelationshipKind="publication_award_crosswalk",SourceWorkID="crossref:"&P,PublicationDOI=P,PublicationPMID="",ReferenceType=Provenance,FromKey="doi:"&P,ToKey=URI,FromLabel=FID,ToLabel=N,ORCID="",ORCIDStatus="Absent",ROR=AuthorityROR,IdentityStatus="Source-supported",SourceURL=Q[url],ObservedUTC=Q[observed_utc],RawSHA256=Q[sha256],SourceVersion=ExpectedBatch,ReviewState="Not reviewed",AuthenticationState="Not authenticated"] else null)))))),
    Output=if List.IsEmpty(Rows) then #table({"EvidenceKey"},{}) else Table.FromRecords(Rows),
    Groups=Table.Group(Output,{"EvidenceKey"},{{"Rows",each Table.Distinct(_),type table}}),
    Result=if List.AllTrue(List.Transform(Groups[Rows],each Table.RowCount(_)=1)) then Table.ToRecords(Table.Distinct(Output,{"EvidenceKey"})) else error "Conflicting repeated Crossref grant assertion"
in List.Buffer(Result)
